INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(9,40121,'voice','-1004346734857',201,'AwACAgQAAyEFAAMBAxXpCQADyWrpGGTh8mC4uYaAdgdSokgBEgXwAAJHDwACK5bJUel8FxTJ4PXIPQQ',replace('✨طريقة دراسة اللغة الفرنسية✨ \n\nأنا جبت ٣','\n',char(10)),replace('✨طريقة دراسة اللغة الفرنسية✨ \n\nأنا جبت ٣٠٠/٣٠٠ \nطيب كيف ؟ 😍\n\n💟 كيف مندرس النصوص ؟\n\n💟 كيف مندرس القواعد ؟\n\n💟 شو منشان الحوار ؟\n\n💟 المواضيع نفسن ؟ \n\nهالتساؤلات كلا موجودة 💜\nلا تآخذونا إذا الفويس طويل بس إن شاء الله مفيد 💜\nفيكن تسرعوا الفويس ×1.5 اذا بتقدروا تركزوا ..\n\n✨ تنويه مهم ( هُنا ) \n\nلا تنسـونَا مِـنْ دعواتِكُـم 📣♥️\n\nhttps://t.me/bacdreamteam','\n',char(10)),1,'2026-11-02 23:10:30',1);
