INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(27,40142,'document','-1004346734857',284,'BQACAgQAAyEFAAMBAxXpCQACARxq6SOHZSD4KLL5C68r_JT9U601aQACKxwAAhOUEFCBpg-ZqLvaQD0E','Emar حوار فرنسي.pdf',replace('السّلام عليكم ورحمة الله وبركاته 🤍\n\nنُقدّم لكم ملفًا يحتوي على : \n💡﴿84﴾ تمرين لترتيب الحوار في اللغة الفرنسية  ، Emar 2022 \n\n• ويضمُّ الملف ✨ :\n\n📌  35 تمرين من نوطة واختبارات ثانوية السّعادة \n📌 29 تمرين من نوطة واختبارات ثانويّة الأوائل .\n📌 20 تمرين من دورات الفرعين العلمي والأدبي من الـ 2020 حتى الـ 2024 .\n\n+ حل جميع التمارين موجود في نهاية المَلف \n\n° وفي حال وجود أي سؤال أو استفسار يُرجى مراجعتنا في كروب المناقشة \n\n• مع تمنيات عارِمة بالتوفيق والـ 300🔥\n\nلا تنسونا من دعوة صالِحة 🤍','\n',char(10)),1,'2026-11-02 23:58:00',1);
