INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(56,40156,'text','-1004346734857',566,NULL,'📍 ليستا مراجعة مادة الفيزياء 📍',replace('📍 ليستا مراجعة مادة الفيزياء 📍\n\n• النواس المرن والفتل والثقلي\n• النواس البسيط\n• السوائل\n• النسبية\n• المغناطيسية\n• فعل الحقل\n• التحريض \n• الدارة المهتزة \n• التيار المتناوب\n• المحولات \n• الأمواج \n• الإلكترونيات\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدرس الذي تريده 🪄','\n',char(10)),1,'2026-11-04 17:20:43',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(59,40175,'text','-1004346734857',586,NULL,'📍دفاتر الأشعة ( 1 + 2 +3 ) :',replace('📍دفاتر الأشعة ( 1 + 2 +3 ) : \n\n🗒 دفاتر القسم كامل : \n\n• لؤي عنتابلي ⇐ (هنا)\n\n• سمير العسة ⇐(هنا)\n\n               •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدفتر الذي تريده 🪄','\n',char(10)),1,'2026-11-04 17:57:08',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(62,40177,'text','-1004346734857',603,NULL,'💭 شروحات الفريق لبعض الأفكار 💭',replace('💭 شروحات الفريق لبعض الأفكار 💭\n\n⏎ قراءة جدول  التغيرات\n⏎ إيجاد النهايات من جدول التغيرات\n⏎ رسالة تشرح الخط البياني\n⏎ فويسات تشرح  الخط بياني\n⏎ التقابل العكسي\n⏎ دراسة الوضع النسبي لمماس المائل\n⏎ استنتاج رسم الخطوط البيانية \n⏎ إثبات الأشكال الرباعية عقدية \n⏎ اللوغ العشري\n⏎ تمثيل بياني لحدود متتالية\n⏎ فكرة إيجاد مجموعة أعداد تحقق ثلاث شروط تحليل توافقي: \n← المثال ( هنا)\n← الشرح ( هنا)\n\n             •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🖇 ملاحظة : اضغط على الكلمة الملوّنة بالأزرق حتى تأخذك إلى الفكرة التي تريد معرفة شرحها🪄','\n',char(10)),1,'2026-11-04 18:53:19',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(65,40180,'text','-1004346734857',615,NULL,'♦️ملخّصات وتجميعات لأساتذة ♦️',replace('♦️ملخّصات وتجميعات لأساتذة ♦️\n\n🔺الاستاذ خلدون شماع:\n\n• ملخص التحليل كامل \n• مخلص الجبر \n• مخلص الأشعة  \n\n🔺الاستاذ طارق سعد الدين + الاستاذ وائل زعترية\n\n• تجميعات أشعة \n• تلخيص عقدية وتطبيقاتها\n• تحليل توافقي\n• تلخيص تكامل وقوانينه\n\n               •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الملخص الذي تريده 🪄','\n',char(10)),1,'2026-11-04 18:56:57',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(67,40182,'text','-1004346734857',624,NULL,'تبدأ المراجعات : (هُنا)',replace('تبدأ المراجعات : (هُنا)\nوتنتهي : (هُنا) \n\n🖇 ملاحظة 1: اضغط على الكلمة الملوّنة بالأزرق حتى تصل إلى هذه المراجعات ✨\n\n🖇 ملاحظة 2 : هذه المراجعات الامتحانيّة عامّة ولا تشمل كل تفاصيل الكتاب','\n',char(10)),1,'2026-11-04 19:05:06',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(68,40176,'text','-1004346734857',636,NULL,'تحدثنا عن طرق لدراسة الرياضيات برسالتين:',replace('تحدثنا عن طرق لدراسة الرياضيات برسالتين:\n\n📨 الرسالة الأولى⇐ (هنا)\n \n📨 الرسالة الثانية ⇐(هنا) \n \n\n 🖇 ملاحظة : اضغط على الكلمة الملوّنة بالأزرق حتى تأخذك إلى الرسالة التي تريدها 🪄','\n',char(10)),1,'2026-11-04 19:15:39',0);
