INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(177,40289,'document','-1004346734857',1208,'BQACAgQAAyEFAAMBAxXpCQACBLhq7M-37mD8K0OfbkdPhyXBAY5rhQADDwACt0pBU7pL3yMTEbdhPQQ','How to write a composition.pdf',replace('عدد كبير من الطلاب بحسوا بمعاناة بما يخص {كتابة موضوع اللغة الانكليزية ✍}\n\nبهاد الملف رح يكون فيه نصائح و خطوات لكتابة الموضوع و ما إلى ذلك🔥\n\nو بإذن الله شامل لكلشي ممكن يخطر ببالكن✨💫\n\nو بالاضافة في نماذج لمواضيع موازية رح تلاقوها بنهاية الملف☺️\nو هي المواضيع بنصحكن تقرأوها لو قراءة\nمشان تاخدوا جمل و تراكيب ممكن توظفوها بأي موضوع رح يجيكن 👌\n\n\nو لا تنسوا..📢📢\nتدربوا عكتابة المواضيع وخصّصوا كل يوم نص ساعة او ساعة حسب برنامجكن\nو اعرضوها عأساتذتكن مشان تتعلموا من أخطائكن و تعالجوها 💯\n\n\nبالتوفيق للجميع 🔥\n\nاتركولنا دعوة♥️','\n',char(10)),1,'2026-11-05 18:49:28',1);
