INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(218,40330,'document','-1004346734857',1381,'BQACAgQAAyEFAAMBAxXpCQACBWVq7Q7eSTZCGA0hzChIMm32ruqHfQACcBQAAmc1EFEGEffN8oij_j0E','الصور البيانية فريق الحلم (1).pdf',replace('• الله يعطيكم العافية فرداً فرداً 💕\n\nومتل ما وعدناكم من فترة إنو رح ننزّللكن شرح الصّور البيانيّة بشكل كامل .. \nوالحمد لله الملف صار جاهز  ، و إن شاء الله مستوفي كلشي و شامل . . \nترتيب الأفكار و التنظيم وطرح بعض الأفكار كان بأسلوبي . . \nف إذا لقيتكن فهمتوا عهاد الملف رح استمر ، واذا ما فهمتوا فـ رح وقف واتفضّى لشي تاني ، \nلهيك رأيكم بهمني وكتير ،،، \n\n+ ممنونين جداً لكل دعوة لطيفة طالعة من قلوبكن 🤍🤍\n\nدُمتم و دُمنا في رعاية الله و توفيقه 💕\n\n• نحن فريق الحلم نحبّكم جداً 🤍','\n',char(10)),1,'2026-11-05 23:18:54',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(220,40331,'document','-1004346734857',1397,'BQACAgQAAyEFAAMBAxXpCQACBXVq7Q_t19sWMzxd13f8U3Oq58BWrAACyh0AAngkwFFYgIQtZiWX7j0E','القواعد .pdf',replace('القواعد \n\n📌الحال ص ١ \n📌الصفة ص ٤\n📌المنادى ص ٦\n📌علامة اعراب أصلية وفرعية ص ٨\n📌الأحرف الزائدة ص ١٣\n📌اسلوب تعجب ص ١٦\n📌اسلوب توكيد ص ١٩\n📌اسلوب شرط ص ٢٢\n📌اسلوب استثناء ص ٢٥\n📌اسلوب مدح وذم ص ٣١ \n📌توكيد لفظي ومعنوي ص ٣٤\n📌البدل ص ٣٦\n📌انواع الأدوات ص ٣٨\n📌المفعول المطلق ص ٤٣ \n📌التمييز ص ٤٦\n📌اسلوب عطف ص ٤٨ \n📌اسماء الأفعال ص ٤٩ \n📌اسلوب الأمر ص ٥١ \n\n🎯ملاحظة: قاعدة عمل اسم الفاعل غير موجودة بالملف \n\n              ❁ Bac Dream team ❁','\n',char(10)),1,'2026-11-05 23:23:25',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(221,40333,'document','-1004346734857',1399,'BQACAgQAAyEFAAMBAxXpCQACBXdq7RARPRt1DXpVZFm4FecqfRF6cAACwBEAAh-XUVHERQ2p71scID0E','جميع_قواعد_اللغة_العربية_للأستاذ_إياد_الشيخ_،_قناة_فريق_الحلم_1.pdf',replace('✨دفتر العربي (قواعد)✨\n\n✨نقدم إليكم ملفاً يحوي جميع قواعد اللغة العربية✨\n\n للأستاذ ﴿إياد الشيخ﴾\n\n🛑 القواعد 🛑\n\n📌 ص١ الاستثناء\n📌 ص٢ التوكيد\n📌 ص٣ المدح والذم \n📌 ص٤ الحال\n📌 ص٥ المنادى \n📌 ص٦ الممنوع من الصرف\n📌 ص٧ علامات الإعراب\n📌 ص٩ الأسماء الخمسة + الإعلال \n📌 ص١٠ الإبدال + المصدر المؤول \n 📌 ص١١ النعت (الصفة)\n📌 ص ١٢ الاستفهام\n📌 ص١٣ أسلوب النفي\n📌 ص١٥ الحروف الزائدة\n📌 ص١٦ أنواع ما \n📌 ص١٧ أنواع لا + توكيد الجمل \n📌 ص١٩ كم\n📌 ص٢٠ التمييز \n📌 ص٢١ أسلوب الشرط\n📌 ص٢٣ المفعول المطلق\n📌 ص٢٤ أسلوب العطف\n📌 ص٢٥ البدل\n📌 ص٢٦ أسلوب الأمر\n📌 ص٢٧ أسم الفعل + التعجب \n📌 ص٢٨ عمل أسم الفاعل \n\nطريقكم نحو ال ٤٠٠ إن شاء الله 💯\n\nتركولنا دعوة♥️','\n',char(10)),1,'2026-11-05 23:24:01',1);
