INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(282,40160,'text','-1004346734857',1879,NULL,'📒 دفاتر الفيزياء الجزئية📒',replace('📒 دفاتر الفيزياء الجزئية📒\n\n• النواس المرن\n • نواس الفتل\n• النواس الثقلي\n• السوائل \n• النسبية\n• المغناطيسية \n• الكهرطيسية\n• التحريض \n• الدارة المهتزة \n• المتناوب\n• المحولات\n• إلكترونيات \n• فلكية\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدفتر الذي تريده 🪄','\n',char(10)),1,'2026-11-07 10:32:08',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(283,40168,'text','-1004346734857',1885,NULL,'📒 ملخصات فيزياء',replace('📒 ملخصات فيزياء  \n📑 ملخصات من عمل طلاب المناقشة :\n\n📍ملخص للمادة كاملة \n\n📍ميكانيك فقط \n\n📍نواسات \n  ⏎ ملخص 2\n  ⏎ ملخص نسبية \n\n📍ميكانيك سوائل + نسبية\n\n📍المغناطيسية\n\n📍فعل الحقل الكهرطيسي \n  ⏎ ملخص 2\n  ⏎ ملخص 3\n  ⏎ ملخص4\n\n📍تحريض\n  ⏎ ملخص 2\n  ⏎ مقارنة بي أصعب القوانين فقط\n  ⏎ ملخص3 \n\n📍دارة مهتزة \n📎 فقرة التفريغ عبر الوشيعة \n\n📍تيار متناوب \n  ⏎ الوصل على التسلسل \n  ⏎ ملخص وملاحظات في الوصل على التسلسل\n  ⏎ مقارنات في الوصل عالتسلسل \n  ⏎ مقارنات\n  ⏎ مقارنات \n  ⏎ ملخص2\n  ⏎ ملخص3\n  ⏎ مقارنات\n  ⏎ مقارنات \n\n📍 أمواج \n  ⏎ ملاحظات\n\n🖇 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الملخص الذي تريده 🪄','\n',char(10)),1,'2026-11-07 10:43:17',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(284,40199,'text','-1004346734857',1889,NULL,'📌 اختبارات القناة :',replace('📌 اختبارات القناة : \n\n←  شامل كيمياء \n← عضوية\n← نووية\n← غازات\n← سرعة وتوازن\n← حموض\n← أوراق عمل عضوية\n←ورقة عمل نووية غازات سرعة توازن \n    حلها ← هنا \n\n🔖 ملاحظة : اضغط على الجملة الملوّنة بالأزرق حتى تأخذك إلى الاختبار الذي تريده🪄','\n',char(10)),1,'2026-11-07 10:54:26',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(285,40201,'text','-1004346734857',1892,NULL,'🌟 ملخصات كيمياء 🌟',replace('🌟 ملخصات كيمياء 🌟\n\n📍نووية\n\n📍غازات \n\n📍ملخص (سرعة + توازن) \n\n📍 نووية + غازات + حموض وأسس\n\n📍 املاح \n\n📍عضوية \n\n✎ مُلاحظة :\nياريت تنتبهوا بالوصف تبع الملف في حال كان الملخص غير شامل أو إذا كان لشي مُعين\n🔖 اضغط على اسم الملخص الذي تريده حتى تصل إليه. \n\n✺ و بالتوفيق من Bac Dream Team ✺\n\n                   •┈┈┈••✦🌟✦••┈┈┈•','\n',char(10)),1,'2026-11-07 11:03:33',0);
