INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(289,40332,'document','-1004346734857',1922,'BQACAgQAAyEFAAMBAxXpCQACBXNq7xMdnryYjlSUoZlPJaPfCvMRZgACASAAAqq4OVG9JIy8wNb3tj0E','CamScanner 02-25-2026 00.09.pdf',replace('📘 نقدم لكم دفتر اللغة العربية 📘\n\n⚡️ للأستاذ إبراهيم علوش ⚡️\n\n﴿ قسم الفوائد والمراجعات _ القواعد _ تطبيق على القصائد ﴾\n\n💫 شامل بإذن الله 💫\n\nمن الٱدمن يمان \nالله يجزيه كل خير🔥','\n',char(10)),1,'2026-11-07 12:02:28',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(290,40172,'text','-1004346734857',1925,NULL,'📍 دفاتر التّحليل واحد :',replace('📍 دفاتر التّحليل واحد :\n( متتاليات - نهاية متتالية - نهايات واستمرار - اشتقاق )\n\n🗒 دفاتر القسم كامل : \n\n• دفتر الآنسة هنادي ⇐ (هنا)\n\n• دفاتر الاستاذ خلدون شماع:\n←نهايات ⇐ (هنا)\n←اشتقاق ⇐ (هنا)\n←متتالية + نهايتها ⇐(هنا)\n            •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n• الجزء الأول كامل حسان وهبة⇐(هنا)\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n🗒 دفاتر حسب ابحاث هذا القسم :\n\n• دفتر متتاليات فقط ل mk ⇐(هنا)\n• دفتر نهاية متتالية فقط ل mk ⇐ (هنا)\n• متتاليات + أسي+ تكامل مجد ميرة  ⇐(هنا)\n            \n            •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدفتر الذي تريده 🪄','\n',char(10)),1,'2026-11-07 12:34:18',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(291,40173,'text','-1004346734857',1928,NULL,'📍دفاتر التحليل 2',replace('📍دفاتر التحليل 2 \n( أسي ـ لوغاريتمي ـ تكامل )\n\n🗒 دفاتر القسم كامل : \n\n• دفتر الاستاذ بشار ⇐(هنا)\n\n• دفتر الٱنسة هنادي⇐ (هنا)\n\n• دفتر الاستاذ خلدون شماع :\n←لوغاريتم ⇐(هنا)\n←أسي ⇐(هنا)\n←تكامل ⇐(هنا)\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🗒 دفاتر حسب ابحاث هذا القسم :\n\n• تكامل فقط  أ.بشار ⇐ (هنا)\nتكامل فقط أ.مجد ميرة ⇐ (هنا)\n• لوغاريتم فقط أ. إيادإدريس ⇐ (هنا)\n• أسي فقط أ. إياد إدريس ⇐ (هنا)\n• تكامل + أسي + متتاليات أ.مجد ميرة⇐ (هنا)\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدفتر الذي تريده 🪄','\n',char(10)),1,'2026-11-07 12:45:40',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(292,40174,'text','-1004346734857',1931,NULL,'📍دفاتر الجبر',replace('📍دفاتر الجبر  \n(عقدية - تطبيقاتها - تحليل توافقي - احتمالات)\n\n🗒 دفاتر القسم كامل : \n• أ. عبد اللطيف⇐ (هنا)\n• أ. مجد ميرة ⇐(هنا)\n• أ.طارق سعد الدين ⇐ (هنا)\n• أ.خلدون ⇐ (هنا)\n• أ.لؤي عنتابلي : \n←عقدية وتطبيقاتها ⇐ (هنا)\n←تحليل توافقي واحتمالات ⇐(هنا)\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🗒 دفاتر حسب ابحاث هذا القسم :\n\n• تحليل توافقي فقط أ.نضال⇐  (هنا)\n• تحليلي توافقي فقط أ.خلدون ⇐(هنا)\n•تحليل توافقي أ.مجد ميرة ⇐ (هنا)\n• تحليل توافقي mk ⇐ (هنا) ــ التتمة ⇐ (هنا)\n• احتمالات أ.مجد ميرة ⇐ (هنا)\n• احتمالات أ.نضال هلال ⇐(هنا)\n• احتمالات خلدون ⇐ (هنا)\n• احتمالات mk ⇐ (هنا)\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الدفتر الذي تريده 🪄','\n',char(10)),1,'2026-11-07 12:48:36',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(293,40181,'text','-1004346734857',1933,NULL,'🌟 ملخصات من عمل طلاب في المناقشة 🌟',replace('🌟 ملخصات من عمل طلاب في المناقشة 🌟\n\n📍 + تحليل 1 + تحليل 2 + جبر+ أشعة \n\n📍قوانين الجزء الأول \n\n📍 جبر فقط\n\n📍نهايات + اشتقاق \n \n📍متتاليات + نهاية متتالية\n  ⏎ ملخص2\n  ⏎ قوانين مهمة في حساب نهاية متتالية\n\n📍 ملخص التابع اللوغاريتمي \n\n📍 ملخص التابع الأسي\n\n📍تكامل \n\n📍عقدية\n  ⏎ ملخص 2\n\n📍تطبيقات عقدية \n  ⏎ العقدية + تطبيقاتها\n\n📍التحليل التوافقي\n  ⏎ توافيق \n\n📍الأشعة \n  • ملخص في إيجاد معادلة مستوي \n ⏎ ملخص1\n  ⏎ ملخص3\n\n📍ليستا ملخصات أحد طلاب المناقشة\n\n               •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🔖 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الملخص الذي تريده 🪄','\n',char(10)),1,'2026-11-07 12:52:09',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(294,40187,'text','-1004346734857',1936,NULL,'📌اختبارات من أبحاث منوّعة 📌',replace('📌اختبارات من أبحاث منوّعة 📌\n\n⇐اشعة + متتاليات+ نهايات ⇐ الحل\n\n⇐ أشعة + عقدية  ⇐ الحل \n\n              •ـــــــــــــــــــــــــــــــــــــــــــ•\n\n🖇 ملاحظة : اضغط على الكلمّة الملوّنة بالأزرق وهي ستأخذك إلى الاختبار الذي تريده 🪄','\n',char(10)),1,'2026-11-07 13:25:50',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(296,40389,'text','-1004346734857',1947,NULL,'🔰 مراجعات سريعة في المواد 🔰',replace('🔰 مراجعات سريعة في المواد 🔰\n\n⚜  ليستا مراجعات دروس الفيزياء \n\n⚜  مراجعات مادة الانكليزي\n\n⚜  مراجعات مادة الرياضيات \n\n⚜  ليستا مراجعات العلوم \n\n⚜  ليستا مراجعات الفرنسي\n\n⚜  مراجعات الديانة\n\n⚜ ليستا مراجعات العربي\n\n⚜ ليستا مراجعات دروس الكيمياء \n\n🔖ملاحظة 1 : اضغط على الكلمة الملوّنة بالأزرق حتى تصل إلى المادة التي تريد مراجعتها🪄\n\n🔖ملاحظة 2 : المراجعات أعلاه عامّة لاستذكار بعض الأفكار عند قرائتها في ليلة أو صباح المادة وليست توقّعات.\n\nاذكرونا بدعوة ♥️','\n',char(10)),1,'2026-11-07 13:35:34',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(297,40390,'voice','-1004346734857',1961,'AwACAgQAAyEFAAMBAxXpCQACB6lq7yn1Z1LpqxNtZ53EfiNgkoaqwwACNyEAAkrIyFDZZD9ympvZcz0E',replace('🔰 نصائح عامة بخصوص اسبوع الفيزياء\n\n00:1','\n',char(10)),replace('🔰 نصائح عامة بخصوص اسبوع الفيزياء\n\n00:15\nكم يوم بينترك للفيزيا؟ وهل فينا ندرس مادة ثانية معها؟\n01:30\nضرورة التنظيم الدراسي وكيف؟\n02:14\nالنماذج ايمتى بتنحل؟وشو اهمية حل شوامل للمادة؟\n03:02\nالجلسات الامتحانية والتوقعات ..؟\nالدراسة من وين؟\n04:14\nالبطء والنسيان خلال دراسة الفيزيا هي الفترة هل هو طبيعي؟ معقول يضيع تعبي وسعيي؟\n05:10\nالرسالة الشاملة يلي رح نبعتلكم ياها\n05:29\nالموبايل وضرورة الابتعاد عنو خلال الدراسة\n05:57\nتأثير المادة الأولى على المعنويات\n\n❁ بالتوفيق الدائم يارب Bac Dream team ❁','\n',char(10)),1,'2026-11-07 13:39:01',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(298,40391,'voice','-1004346734857',1963,'AwACAgQAAyEFAAMBAxXpCQACB6tq7yow35_SJwNR-rYvRNE2USTZZwAC7hEAAn0kQVMvL96OU6gMbj0E',replace('✅ فويس الكيمياء ✅\n\n1⃣ من وين راجع\n2⃣ كيف','\n',char(10)),replace('✅ فويس الكيمياء ✅\n\n1⃣ من وين راجع\n2⃣ كيف قسم المادة \n3⃣ شو حل \n4⃣ العضوية \n5⃣ الدورات\n6⃣ التعامل مع الورقة\n7⃣ ال 200\n8⃣ فكرة صار وقتها\n\n✨ ليستا الكيميا ✨\n\n✨ دورات الكيمياء ✨\n\n✅ موفّقين','\n',char(10)),1,'2026-11-07 13:40:00',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(299,40393,'voice','-1004346734857',1965,'AwACAgQAAyEFAAMBAxXpCQACB61q7ypC9FFq1zwUJXRrmS8ythPXLgAC6x8AAlVWaVHOAarXuXOpbD0E',replace('🎙 فويس مادة علم الأحياء ✔️\n\n😀 تقسيم و ','\n',char(10)),replace('🎙 فويس مادة علم الأحياء ✔️\n\n😀 تقسيم و كيفيّة دراسة المادة 💡\n00:10\n\n😀 مصدر مراجعة المادة 📖\n3:50 \n\n😀 رسمات الكتاب 🖊\n4:30\n\n😀 اختبارات أسئلة الوحدة❔\n6:06\n\n😀 التعامل مع الورقة الامتحانية 📃\n7:17\n\n• ليستا المادة 🖊\n\n\nبالتوفيق 🤎','\n',char(10)),1,'2026-11-07 13:40:18',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(300,40392,'voice','-1004346734857',1967,'AwACAgQAAyEFAAMBAxXpCQACB69q7ypWZIO2HauO-tdAk89seUJRxQACGyEAAqscQFHi721VTO2-Jz0E',replace('📌فويس مادّة الرّياضيات✅\n\n1⃣خلصنا إنجليز','\n',char(10)),replace('📌فويس مادّة الرّياضيات✅\n\n1⃣خلصنا إنجليزي .. شو هلق ؟💪\n➡️00:03\n\n2⃣أسجل بمكثفة ولا أدرس لحالي؟ وإذا مقصر شو أعمل؟❕\n➡️00:40\n\n3⃣حل كل تمرين بالحرف ولا ركز ع الفكرة؟ وشو وضع الدورات؟📔\n➡️02:30\n\n5⃣شو رح أعمل يوم الجمعة؟ وكيف بتعامل مع ورقة الامتحان؟ 🕑\n➡️03:21\n\n5⃣تعبان وخايف؟ اسمع هالكلمتين🔥\n➡️05:00','\n',char(10)),1,'2026-11-07 13:40:38',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(301,40394,'voice','-1004346734857',1969,'AwACAgQAAyEFAAMBAxXpCQACB7Fq7yqxNUJ7PD5cpyKzZxQH03gougACHh0AAnSMyVPjx4ki3m8WmD0E',replace('🔰 فويس اللغة العربية 🔰\n\n⚜ لمحة عامة عن','\n',char(10)),replace('🔰 فويس اللغة العربية 🔰\n\n⚜ لمحة عامة عن المادة \n\n⚜ كيفية التعامل مع المادة \n\n⚜ بعض الملاحظات عن المواضيع \n\n⚜ أهمية نظافة الورقة','\n',char(10)),1,'2026-11-07 13:42:09',1);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(302,40395,'voice','-1004346734857',1971,'AwACAgQAAyEFAAMBAxXpCQACB7Nq7yrTm_LFT9YTIi2X9cGpLaC5owACcBEAAmQLmFJiqdvi5yxxzj0E',replace('🦋 فويس الفرنسي 🦋\n\n• خلّينا ننسىٰ الفيز','\n',char(10)),replace('🦋 فويس الفرنسي 🦋\n\n• خلّينا ننسىٰ الفيزياء ✔️\n\n✅ أحسن طريقة لنراجع المادة \n\n✅ شويّة نصائح لبعض التساؤلات \n\n✅ كيف ما ننسى الموضوع \n\n✅ الدورات و شو نعيد بآخر  لحظات الدراسة \n\nال 300 بانتظاركم ♥️','\n',char(10)),1,'2026-11-07 13:42:43',1);
