INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(305,40400,'text','-1004346734857',1993,NULL,'🔴 أهم قنوات اليوتيوب في البكلوريا 🔴',replace('🔴 أهم قنوات اليوتيوب في البكلوريا 🔴\n\n📚 مادة الرياضيات 📚\n💡قناة  MK Academy مفيدة لشرح المنهاج : https://youtube.com/@mk.syr.academy?si=EBCj3hL0vB4P0En2\n\n💡قناة لحل كافة الأسئلة و التمارين في كتاب الرياضيات تقريبا: https://youtube.com/@asemasemalzouaby8010?si=tX24hziRgxY-bIiz\n\n💡قناة لتناول الرياضيات بشكل ثلاثي الأبعاد : https://youtube.com/@aiyhamalshaer?si=L-m4_RPdmjxMUgGT\n\n💡قناة في النكشات و التمارين الصعبة لمادة الرياضيات للاستاذ محمود المحمود : ⬅️https://youtube.com/@ch_x_mathbac?si=R8CzbPjVpreNstl5\n\n📚 مادة الفيزياء 📚\n💡قناة الأستاذ مؤيد بكر : https://youtube.com/@moaiadbakr?si=CU0z_SKMDkQ6FIsJ\n\n💡قناة الأستاذ أنس الأحمد (القناة المميزة بشرح وحدة الإلكترونيات و الفلكية) : https://youtube.com/@myway.education?si=IAi0ITX99lH7KGk6\n\n📚 مادة الكيمياء📚\n💡قناة الأستاذ طارق غبرا : https://youtube.com/@user-bx9ne8iz2c?si=oNm9FCnd_6YEuoPh\n\n💡قناة الأستاذ أسامة الحصري: https://youtube.com/@-.3613?si=gfsr_m39lLChGNPg\n\n📚 مادة العلوم 📚\n💡قناة بارعة و العلوم(رحلة ثلاثية الأبعاد في جسم الإنسان): https://youtube.com/@bariaaandbio?si=LAQ9Ep-sCxvWW76B\n\n💡قناة الأستاذ محمد عرابي: https://youtube.com/@mohammadorabi9404?si=pkVuQcNAtTAoQfwP\n\n\n📚 مادة اللغة الإنكليزية📚\n💡رحلة ممتعة مع الصور في نصوص اللغة مع قناة متخصصة لشرح منهاج إيمار بكامل الأقسام(استماع-محادثة-قراءة-كتابة-قواعد): https://youtube.com/@msenglish123?si=B42kimlOIh_EbTNP\n\n💡قناة علي الدرساني: https://youtube.com/@alialdarsani?si=jvYx3I088MjMMfO-\n\n📚 مادة اللغة الفرنسية 📚\n💡قناة مدام مها لشرح كافة صفوف المنهاج السوري من السابع إلى البكلوريا إضافة إلى الجامعات⬅️https://youtube.com/@mahaaltanji?si=14gBxiRvzfI0GeFw\n\n📚 مادة اللغة العربية 📚\n💡قناة الأستاذ عمر السويد⬅️https://youtube.com/@user-sh3el9pu4l?si=5QGt1B_E49TGTD_-\n\n💡قناة الأستاذ رامي التكريتي: https://youtube.com/@ramitakriti2014?si=-1UOyzduTwsZuiQ2\n\n🔍 *_كنتم مع باقة لأهم الأدوات و الوسائل الميسرة لطالب البكلوريا بإشراف و تجميع و تنسيق الطالب مصعب الدايه *_ 🔍 \n\n📌في الختام كنت طالب مثلكم أتمنى الحصول على مثل تلك الأدوات المساعدة على طبق من ذهب لكن شاء القدر أن أجمّعها و أبحث عنها بيدي، لذلك نرجو منكم ألّا تنسونا من صالح دعائكم بالتوفيق و الخير.📌','\n',char(10)),1,'2026-11-07 14:59:17',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(307,40398,'text','-1004346734857',1998,NULL,'📣 المنصات',replace('📣 المنصات \n\n📩 في كثير خيارات وبكون أفضلها : \nhttps://t.me/dreamteambac/433192\n\n🔍 فيني جيب علامات من دراسة النت ؟ \n1- https://t.me/dreamteambac/430622\n\n2- https://t.me/dreamteambac/430627\n\n🔺ملخص تجربة المنصات:\nhttps://t.me/dreamteambac/775073\n\n🔻تجربة منصة طريقي \n1- https://t.me/dreamteambac/399523\n\n2- https://t.me/dreamteambac/399529\n\n📩 تقسيم الوقت الدراسي  ، تسجيل أفكاره بتفيدك :\nhttps://t.me/dreamteambac/437745','\n',char(10)),1,'2026-11-07 15:03:07',0);
INSERT INTO "node_contents" ("id","node_id","content_type","source_chat_id","source_message_id","file_id","title","caption","sort_order","created_at","is_forwarded") VALUES(308,40399,'text','-1004346734857',2001,NULL,'أساتذة عالنت كاملين',replace('أساتذة عالنت كاملين\n\n💡 فيزياء:\n• مؤيد بكر  • فارس جقل • أنس أحمد\n\n💡 كيمياء: \n• محمود كعكة • سامح غلاب • طارق غبرة\n• فارس جقل • أسامة الحصري • فيصل الدخيل\n\n💡رياضيات:\n• فارس جقل • عادل طنيش • إبراهيم آغا\n• عبد العزيز شملان • وضاح معلا \n• قناة math plus syria\n• المحترف\n• فراس النجار • رشدي جوخه دار\n• أمير سكيكر • عبد العزيز الشملان\n• صهيب جاموس • منصةMK\n\n💡 عربي:\n• همام حمدان • رغد الساطي • رامي تكريتي\n• خليل الشيخ • طالب حسينو • كرم كيوان\n• عبد اللطيف ضعيف • طارق الخابور\n\n💡 فرنسي: \n• محمود مرندي • حسام العشي \n•اللاذقية Raim Zwsn \n• منهاج و قواعد Maha Altanji \n\n💡 إنكليزي: \n• خالد غزالة • مهند دين • أحمد اسماعيل • علي الدرساني\n\n💡علوم :\n• نضال أقجة • جلال عكيل • علي شباط\n• لمى نصيرات • رهف تسابحجي \n• حازم ضعيف • أمير الحسين\n\n💡 ديانة:\n• أبو مسلم العنداني\n• ياسر العبيد • محمد سعيد آل رشي','\n',char(10)),1,'2026-11-07 15:13:51',0);
