PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE menu_nodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NULL,
    title TEXT NOT NULL,
    description TEXT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')), views_count INTEGER NOT NULL DEFAULT 0, is_full_width INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (parent_id) REFERENCES menu_nodes(id) ON DELETE CASCADE
);
CREATE TABLE node_contents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    node_id INTEGER NOT NULL,
    content_type TEXT NOT NULL, -- 'document' | 'video' | 'audio' | 'voice' | 'photo' | 'text' | 'other'
    source_chat_id TEXT NOT NULL,
    source_message_id INTEGER NOT NULL,
    file_id TEXT NULL,
    title TEXT NOT NULL,
    caption TEXT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), is_forwarded INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (node_id) REFERENCES menu_nodes(id) ON DELETE CASCADE
);
CREATE TABLE admin_sessions (
    user_id TEXT NOT NULL,
    chat_id TEXT NOT NULL,
    action TEXT NOT NULL DEFAULT 'IDLE', -- 'IDLE' | 'ADD_CHILD_NODE' | 'RENAME_NODE' | 'EDIT_NODE_DESC' | 'ADD_CONTENT'
    target_node_id INTEGER NULL,
    panel_message_id INTEGER NULL,
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (user_id, chat_id)
);
CREATE TABLE bot_users (
    user_id TEXT PRIMARY KEY,
    username TEXT NULL,
    first_name TEXT NULL,
    is_active INTEGER NOT NULL DEFAULT 1, -- 1 = فعال، 0 = قام بحظر البوت
    joined_at TEXT NOT NULL DEFAULT (datetime('now')),
    last_active_at TEXT NOT NULL DEFAULT (datetime('now'))
, current_node_id INTEGER NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_menu_nodes_parent_sort
    ON menu_nodes(parent_id, sort_order, id);
CREATE INDEX idx_node_contents_node_sort
    ON node_contents(node_id, sort_order, id);
CREATE INDEX idx_bot_users_active
    ON bot_users(is_active);
